  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();
  const s = Math.min(width, height) / 1080;

  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Layout math
  const cardW = 340 * s;
  const cardH = 80 * s;
  const centerW = 380 * s;
  const centerH = 400 * s;

  const leftX = 140 * s;
  const rightX = width - leftX - cardW;
  const centerX = width / 2;
  const centerY = height / 2;

  const inputSpacing = 110 * s;
  const outputSpacing = 110 * s;

  const startYInputs = centerY - ((inputCards.length - 1) * inputSpacing) / 2;
  const startYOutputs = centerY - ((outputCards.length - 1) * outputSpacing) / 2;

  // Center connection points (squeezed to fit center engine height)
  const centerConnSpan = centerH * 0.7;
  const centerLeftStartY = centerY - centerConnSpan / 2;
  const centerRightStartY = centerY - centerConnSpan / 2;

  // Timings
  const STAGGER = 12;
  const CENTER_ENTER = 15;
  const INPUTS_START = 30;
  const LINE_DRAW_DUR = 25;
  const PULSE_START = INPUTS_START + (inputCards.length * STAGGER) + LINE_DRAW_DUR;
  const OUTPUTS_START = PULSE_START + 30;

  // Center Engine Animation
  const centerEntry = spring({ fps, frame: Math.max(0, frame - CENTER_ENTER), config: { damping: 14 } });
  const centerScale = interpolate(centerEntry, [0, 1], [0.8, 1]);
  const centerOpacity = interpolate(frame, [CENTER_ENTER, CENTER_ENTER + 10], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // Calculate accumulated inputs to drive center glow
  const activeInputsCount = inputCards.reduce((acc, _, i) => {
    const lineEndFrame = INPUTS_START + i * STAGGER + LINE_DRAW_DUR;
    const contribution = interpolate(frame, [lineEndFrame - 5, lineEndFrame + 5], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
    return acc + contribution;
  }, 0);
  const glowIntensity = interpolate(activeInputsCount, [0, inputCards.length], [0.1, 1]);

  const pulse = interpolate(frame, [PULSE_START, PULSE_START + 10, PULSE_START + 20], [1, 1.05, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
